/**
 * Where an asset came from (P3-B6, P3-B7, P3-V6, P3-V18): captured by a camera (everything before Phase 3),
 * generated by a provider, from a bundled pack (CC0, or MIT for code-made renders: EAR1, D22), or a stock item
 * under its licence. On AssetSummary; the renderer shows a Generated, CC0, Code-made or Stock chip from it, and
 * render's credits and AI inventory read it. A generated file records the prompt's hash, never the prompt.
 */
import '../basics/zod-config';
import { z } from 'zod';
import { idSchema } from '../basics/ids';
import { C2PA_PRESENCES } from '../render/content-credentials';
import { sha256Schema } from '../templates/template-parts';
import { STOCK_LICENCES, STOCK_PROVIDERS } from './stock';

/**
 * AGT2 sbx: `workspace` is media the agent's own code made in its workspace shell (FFmpeg, Python, a HyperFrames
 * render), kept by workspace.importMedia: provider 'taalcut', access 'local', and `promptSha256` the sha256 of the
 * file's bytes (the code that made it is in the workspace's revisions, not in the asset).
 */
export const GENERATION_KINDS = ['voice', 'music', 'soundEffect', 'image', 'workspace'] as const;
export type GenerationKind = (typeof GENERATION_KINDS)[number];
export const GENERATION_ACCESS = ['api-key', 'openrouter', 'subscription', 'local'] as const;

export const capturedProvenanceSchema = z.object({ kind: z.literal('captured') });

export const generatedProvenanceSchema = z.object({
  kind: z.literal('generated'),
  generation: z.enum(GENERATION_KINDS),
  provider: z.string().min(1).max(64),
  model: z.string().min(1).max(128),
  access: z.enum(GENERATION_ACCESS),
  /** Voice only: drafts on the fast model, finals on the flagship. */
  quality: z.enum(['draft', 'final']).nullable(),
  promptSha256: sha256Schema,
  /** Voice only: the provider's voice id (a clone's id links to its consent). */
  voiceId: z.string().max(64).nullable(),
  /** The provider's id for the result, never a URL. */
  providerRef: z.string().max(128).nullable(),
  /** Read from the bytes at ingest; never added or removed. */
  c2pa: z.enum(C2PA_PRESENCES),
  /** Separately billed API spend; subscription quota consumption is not a dollar price. */
  costUsd: z.number().nonnegative(),
  runId: idSchema<'AgentRun'>().nullable(),
  createdAt: z.int().nonnegative(),
});
export type GeneratedProvenance = z.output<typeof generatedProvenanceSchema>;

/** EAR1 (D22): `sfx-bank` is earshot's SFX bank, rendered from code at build time. */
export const BUNDLED_PACKS = ['music-pack', 'sfx-pack', 'sfx-bank'] as const;
export type BundledPack = (typeof BUNDLED_PACKS)[number];
/**
 * What a bundled item may be under (D22): a CC0 dedication, or MIT for a sound Taalcut's build renders from code
 * (the SFX bank; the window shows it as "Code-made"). Both ask for no credit line.
 */
export const BUNDLED_LICENCES = ['CC0-1.0', 'MIT'] as const;
export type BundledLicence = (typeof BUNDLED_LICENCES)[number];
export const bundledProvenanceSchema = z.object({
  kind: z.literal('bundled'),
  pack: z.enum(BUNDLED_PACKS),
  itemId: z.string().min(1).max(64),
  licence: z.enum(BUNDLED_LICENCES),
  sourceUrl: z.url().max(500),
  title: z.string().min(1).max(120),
});

/** A stock item and its licence as the provider stated it. */
export const stockProvenanceSchema = z.object({
  kind: z.literal('stock'),
  provider: z.enum(STOCK_PROVIDERS),
  providerAssetId: z.string().max(100),
  licence: z.enum(STOCK_LICENCES),
  /** The provider's own value, verbatim ('Attribution', a deed URL). */
  rawLicence: z.string().max(200),
  author: z.string().max(200).nullable(),
  authorUrl: z.url().max(2048).nullable(),
  sourceUrl: z.url().max(2048).nullable(),
  /** The credit line the licence asks for; '' when none. */
  attribution: z.string().max(500),
  fetchedAt: z.int().nonnegative(),
});
export type StockProvenance = z.output<typeof stockProvenanceSchema>;

export const ASSET_PROVENANCE_KINDS = ['captured', 'generated', 'bundled', 'stock'] as const;
export const assetProvenanceSchema = z.discriminatedUnion('kind', [
  capturedProvenanceSchema,
  generatedProvenanceSchema,
  bundledProvenanceSchema,
  stockProvenanceSchema,
]);
export type AssetProvenance = z.output<typeof assetProvenanceSchema>;

/** What every asset recorded before Phase 3 is. */
export const CAPTURED: AssetProvenance = { kind: 'captured' };
